import java.util*;
class Chef{
    final int basicSalary=50000;
    int totalpay;
    final int calculatePay(int workingDays){
        totalpay=basicSalary+(workingDays*500);
        return totalpay;
    }
}

final class HeadChef extends Chef{
    void displayRole(){
       System.out.println("Head Chef"); 
    }
}

public class Main(){
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int workingDays=sc.nextInt();
        HeadChef chef=new HeadChef();
        h.displayRole();

        System.out.println("Basic Salary: "+h.basicSalary);
        System.out.println("Total Pay: "+ h.calculatePay(workingDays));

        sc.close();

    }
}

